1	// Route tests for the Jotter demo (real HTTP via fetch, no Kane).
2	// They pin the demo's contract: the three seeded bugs are present, and guests are blocked.
3	// Run: npx vitest run --root demo
4	import fs from 'node:fs';
5	import os from 'node:os';
6	import path from 'node:path';
7	import { afterAll, beforeAll, describe, expect, it } from 'vitest';
8	import { createApp } from '../app.js';
9	import { openDb } from '../db.js';
10	import { DEFAULT_PASSWORDS, DEFAULT_TOKENS, loadTokens, seed } from '../seed.js';
11	
12	const ALICE = { email: 'alice@jotter.test', password: DEFAULT_PASSWORDS.alice, token: DEFAULT_TOKENS.alice };
13	const BOB = { email: 'bob@jotter.test', password: DEFAULT_PASSWORDS.bob, token: DEFAULT_TOKENS.bob };
14	
15	let server;
16	let base;
17	
18	beforeAll(async () => {
19	  const db = await openDb(); // in-memory
20	  seed(db, { tokens: { ...DEFAULT_TOKENS }, passwords: { ...DEFAULT_PASSWORDS } });
21	  server = createApp(db).listen(0, '127.0.0.1');
22	  await new Promise((r) => server.once('listening', r));
23	  base = `http://127.0.0.1:${server.address().port}`;
24	});
25	
26	afterAll(() => new Promise((r) => server.close(r)));
27	
28	/** A tiny cookie-keeping client. Redirects are not followed so tests can assert on them. */
29	function client() {
30	  let cookie = '';
31	  return async function req(method, url, form) {
32	    const res = await fetch(base + url, {
33	      method,
34	      redirect: 'manual',
35	      headers: {
36	        ...(cookie ? { cookie } : {}),
37	        ...(form ? { 'content-type': 'application/x-www-form-urlencoded' } : {}),
38	      },
39	      body: form ? new URLSearchParams(form).toString() : undefined,
40	    });
41	    const set = res.headers.get('set-cookie');
42	    if (set) cookie = set.split(';')[0];
43	    return { status: res.status, location: res.headers.get('location'), headers: res.headers, text: await res.text() };
44	  };
45	}
46	
47	async function loginAs(who) {
48	  const req = client();
49	  const res = await req('POST', '/login', { email: who.email, password: who.password });
50	  expect(res.status).toBe(302);
51	  return req;
52	}
53	
54	describe('guests are blocked (no false alarms)', () => {
55	  const guest = client();
56	
57	  it('GET /notes/1001 redirects to /login without the token', async () => {
58	    const res = await guest('GET', '/notes/1001');
59	    expect(res.status).toBe(302);
60	    expect(res.location).toBe('/login?next=%2Fnotes%2F1001');
61	    expect(res.text).not.toContain(ALICE.token);
62	  });
63	
64	  it('GET /api/notes/1001 is 401 without the token', async () => {
65	    const res = await guest('GET', '/api/notes/1001');
66	    expect(res.status).toBe(401);
67	    expect(res.text).not.toContain(ALICE.token);
68	  });
69	
70	  it('every private page redirects to /login', async () => {
71	    for (const url of ['/notes', '/notes/new', '/notes/1002', '/account', '/pro/export']) {
72	      const res = await guest('GET', url);
73	      expect(res.status, url).toBe(302);
74	      expect(res.location, url).toMatch(/^\/login\?next=/);
75	    }
76	  });
77	
78	  it('POST /api/export is 401', async () => {
79	    const res = await guest('POST', '/api/export');
80	    expect(res.status).toBe(401);
81	  });
82	});
83	
84	describe('positive controls', () => {
85	  it("Alice sees her own note 1001 with her token, in the page and the API", async () => {
86	    const alice = await loginAs(ALICE);
87	    const pageRes = await alice('GET', '/notes/1001');
88	    expect(pageRes.status).toBe(200);
89	    expect(pageRes.text).toContain(`Passport no. ${ALICE.token}`);
90	    const api = await alice('GET', '/api/notes/1001');
91	    expect(JSON.parse(api.text)).toMatchObject({ id: 1001, owner_email: ALICE.email, body: `Passport no. ${ALICE.token}` });
92	  });
93	
94	  it("Bob's /notes lists only his note and /account shows his token in the bio", async () => {
95	    const bob = await loginAs(BOB);
96	    const list = await bob('GET', '/notes');
97	    expect(list.text).toContain('href="/notes/1002"');
98	    expect(list.text).toContain(BOB.token);
99	    expect(list.text).not.toContain('href="/notes/1001"');
100	    expect(list.text).not.toContain(ALICE.token);
101	    const account = await bob('GET', '/account');
102	    expect(account.text).toContain(BOB.token);
103	    expect(account.text).toContain('Jotter Free');
104	    expect(account.text).not.toContain(ALICE.token);
105	  });
106	
107	  it('wrong password is rejected', async () => {
108	    const req = client();
109	    const res = await req('POST', '/login', { email: BOB.email, password: '[redacted]' }); // notyours:allow-secret (fake test value)
110	    expect(res.status).toBe(401);
111	    expect(res.text).toContain('Wrong email or password');
112	  });
113	});
114	
115	describe('seeded bugs are present', () => {
116	  it('SEEDED BUG #1: Bob can open Alice\'s note page /notes/1001', async () => {
117	    const bob = await loginAs(BOB);
118	    const res = await bob('GET', '/notes/1001');
119	    expect(res.status).toBe(200);
120	    expect(res.text).toContain(ALICE.token);
121	  });
122	
123	  it('SEEDED BUG #2: Bob can fetch Alice\'s full record from /api/notes/1001', async () => {
124	    const bob = await loginAs(BOB);
125	    const res = await bob('GET', '/api/notes/1001');
126	    expect(res.status).toBe(200);
127	    expect(JSON.parse(res.text)).toMatchObject({ id: 1001, owner_id: 1, owner_email: ALICE.email });
128	    expect(res.text).toContain(ALICE.token);
129	  });
130	
131	  it('SEEDED BUG #3: free Bob has no export button, but POST /api/export works anyway', async () => {
132	    const bob = await loginAs(BOB);
133	    const ui = await bob('GET', '/pro/export');
134	    expect(ui.status).toBe(200);
135	    expect(ui.text).not.toContain('action="/api/export"');
136	    expect(ui.text).toContain('Export is a Jotter Pro feature');
137	
138	    const res = await bob('POST', '/api/export');
139	    expect(res.status).toBe(200);
140	    expect(res.headers.get('content-type')).toMatch(/^text\/plain/);
141	    expect(res.headers.get('content-disposition')).toContain('jotter-export.txt');
142	    expect(res.text).toContain(BOB.token);
143	    expect(res.text).not.toContain(ALICE.token);
144	  });
145	
146	  it('GET /api/export is 405 with Allow: POST (never a 404), for Bob and for guests', async () => {
147	    const bob = await loginAs(BOB);
148	    for (const req of [bob, client()]) {
149	      const res = await req('GET', '/api/export');
150	      expect(res.status).toBe(405);
151	      expect(res.headers.get('allow')).toBe('POST');
152	      expect(res.text).not.toContain(BOB.token);
153	    }
154	  });
155	
156	  it('Pro Alice sees the export button and exports only her notes', async () => {
157	    const alice = await loginAs(ALICE);
158	    const ui = await alice('GET', '/pro/export');
159	    expect(ui.text).toContain('action="/api/export"');
160	    const res = await alice('POST', '/api/export');
161	    expect(res.text).toContain(ALICE.token);
162	    expect(res.text).not.toContain(BOB.token);
163	  });
164	});
165	
166	describe('happy paths', () => {
167	  it('signup -> create note -> view it -> logout', async () => {
168	    const req = client();
169	    const signup = await req('POST', '/signup', { name: 'Carol', email: 'carol@jotter.test', password: '[redacted]' }); // notyours:allow-secret (fake test value)
170	    expect(signup.status).toBe(302);
171	    expect(signup.location).toBe('/notes');
172	
173	    const empty = await req('GET', '/notes');
174	    expect(empty.text).toContain('No notes yet');
175	
176	    const created = await req('POST', '/notes/new', { title: 'Shopping', body: 'eggs & <milk>' });
177	    expect(created.status).toBe(302);
178	    const id = Number(created.location.split('/').pop());
179	    expect(id).toBeGreaterThan(1002);
180	
181	    const view = await req('GET', created.location);
182	    expect(view.status).toBe(200);
183	    expect(view.text).toContain('eggs &amp; &lt;milk&gt;'); // escaped
184	
185	    const account = await req('GET', '/account');
186	    expect(account.text).toContain('Jotter Free');
187	
188	    const out = await req('GET', '/logout');
189	    expect(out.location).toBe('/login');
190	    expect((await req('GET', '/notes')).status).toBe(302);
191	  });
192	
193	  it('login honours a safe ?next= and ignores an off-site one', async () => {
194	    const req = client();
195	    const ok = await req('POST', '/login?next=%2Faccount', { email: BOB.email, password: BOB.password });
196	    expect(ok.location).toBe('/account');
197	    const req2 = client();
198	    const evil = await req2('POST', '/login?next=%2F%2Fevil.test', { email: BOB.email, password: BOB.password });
199	    expect(evil.location).toBe('/notes');
200	  });
201	
202	  it('duplicate signup and empty notes are rejected', async () => {
203	    const req = client();
204	    const dup = await req('POST', '/signup', { name: 'B', email: BOB.email, password: '[redacted]' }); // notyours:allow-secret (fake test value)
205	    expect(dup.status).toBe(400);
206	    const bob = await loginAs(BOB);
207	    const bad = await bob('POST', '/notes/new', { title: '', body: '' });
208	    expect(bad.status).toBe(400);
209	  });
210	
211	  it('unknown note ids are 404', async () => {
212	    const bob = await loginAs(BOB);
213	    expect((await bob('GET', '/notes/999999')).status).toBe(404);
214	    expect((await bob('GET', '/api/notes/abc')).status).toBe(404);
215	  });
216	});
217	
218	describe('duplicate note', () => {
219	  it('owner sees a Duplicate button and gets an independent copy', async () => {
220	    const req = client();
221	    await req('POST', '/signup', { name: 'Dana', email: 'dana@jotter.test', password: '[redacted]' }); // notyours:allow-secret (fake test value)
222	    const created = await req('POST', '/notes/new', { title: 'Recipe', body: 'flour\n& <sugar>' });
223	    const id = Number(created.location.split('/').pop());
224	
225	    const view = await req('GET', `/notes/${id}`);
226	    expect(view.text).toContain(`action="/notes/${id}/duplicate"`);
227	
228	    const dup = await req('POST', `/notes/${id}/duplicate`);
229	    expect(dup.status).toBe(302);
230	    const copyId = Number(dup.location.split('/').pop());
231	    expect(copyId).toBeGreaterThan(id);
232	
233	    const copy = await req('GET', dup.location);
